import functools
import typing

import pydantic


def schema_check(schema: typing.Type[pydantic.BaseModel]):
    def check(func):
        @functools.wraps(func)
        def wrapper(*args, **kwargs):
            result = func(*args, **kwargs)
            # schema.parse_obj(result)  # noqa: ERA001
            return result  # noqa: RET504

        return wrapper

    return check
